import test from 'node:test';
import assert from 'node:assert/strict';
import { createEngineeringPackage, validateProject, verifyBinding, comparePackages, emptyDiscipline, hash } from '../src/index.mjs';
import { coordinate } from '../src/coordination.mjs';
import { fixture } from './helpers.mjs';
test('complete demo is deterministic, immutable and bound to its input', async () => { const p = fixture(), before = JSON.stringify(p); const a = await createEngineeringPackage(p), b = await createEngineeringPackage(p); assert.deepEqual(a, b); assert.equal(JSON.stringify(p), before); assert.ok(Object.isFrozen(a.disciplines)); assert.equal(await verifyBinding(a, p), true); assert.equal(a.constructionApproved, false); });
test('missing calculation inputs stay null and create a missing-input issue', async () => { const p = fixture(); delete p.services.electrical.loads[0].powerFactor; const r = await createEngineeringPackage(p, { disciplines: ['electrical'] }); const c = r.disciplines[0].calculations.find(c => c.id === 'E-P-SO1'); assert.equal(c.status, 'NOT_CALCULATED'); assert.equal(c.value, null); assert.ok(r.issues.some(i => i.code === 'CALCULATION_INPUT_REQUIRED')); });
test('empty system never produces a code-compliant or construction-ready design', async () => { const p = fixture(); p.services = {}; const r = await createEngineeringPackage(p); assert.equal(r.constructionApproved, false); assert.equal(r.codeCompliance, 'NOT_EVALUATED'); assert.ok(r.issues.length > 0); assert.ok(r.disciplines.every(d => d.devices.length === 0)); });
test('duplicate circuit assignment is rejected without double-counting', async () => { const p = fixture(); p.services.electrical.circuits[1].loadIds.push('SO1'); const r = await createEngineeringPackage(p, { disciplines: ['electrical'] }); assert.ok(r.issues.some(i => i.code === 'CIRCUIT_REFERENCE_INVALID')); assert.equal(r.status, 'BLOCKED_PRELIMINARY'); });
test('unassigned loads are explicitly identified', async () => { const p = fixture(); p.services.electrical.circuits.shift(); const r = await createEngineeringPackage(p, { disciplines: ['electrical'] }); assert.ok(r.issues.some(i => i.code === 'UNASSIGNED_LOAD' && i.details.loadId === 'SO1')); });
test('unknown phase assignment yields null phase totals', async () => { const p = fixture(); delete p.services.electrical.circuits[0].phase; const r = await createEngineeringPackage(p, { disciplines: ['electrical'] }); const panel = r.disciplines[0].schedules.find(s => s.id === 'electrical-panels').rows[0]; assert.equal(panel.phaseL1VA, null); assert.ok(r.issues.some(i => i.code === 'PHASE_BALANCE_NOT_EVALUATED')); });
test('electrical and cooling quantities cannot be substituted at an interface', async () => { const p = fixture(); p.services.hvac.equipment[0].ratedInputW = 5000; const r = await createEngineeringPackage(p); assert.ok(r.coordination.interfaces.some(i => i.outcome === 'POWER_MISMATCH')); });
test('wrong drainage end invert is blocked and excluded from quantities', async () => { const p = fixture(); p.services.plumbing.connections[1].endInvertM = -.8; const r = await createEngineeringPackage(p, { disciplines: ['plumbing'] }); const drain = r.disciplines[0].routes.find(r => r.kind === 'sanitary'); assert.equal(drain.status, 'BLOCKED'); assert.ok(r.issues.some(i => i.code === 'OUTFALL_INVERT_MISMATCH')); assert.ok(!r.quantities.rows.some(x => x.layer === 'P-DRAIN')); });
test('drainage elevations descend by horizontal distance times slope', async () => { const r = await createEngineeringPackage(fixture(), { disciplines: ['plumbing'] }); const pipe = r.disciplines[0].routes.find(r => r.kind === 'sanitary'); assert.equal(pipe.status, 'PROPOSED'); assert.ok(Math.abs(pipe.points.at(-1).z + .342) < 1e-8); assert.ok(pipe.points.every((p, i, a) => i === 0 || p.z <= a[i - 1].z)); });
test('sloped drainage is rechecked at the final elevation', async () => { const p = fixture(); p.architecture.obstacles.push({ id: 'UNDERGROUND', min: { x: 11.4, y: 8.9, z: -.34 }, max: { x: 11.5, y: 9.1, z: -.32 } }); const r = await createEngineeringPackage(p, { disciplines: ['plumbing'] }); assert.ok(r.disciplines[0].routes.some(r => r.kind === 'sanitary' && r.status === 'BLOCKED')); });
test('unpriced quantities remain unpriced and total is null', async () => { const r = await createEngineeringPackage(fixture()); assert.ok(r.quantities.unpricedCount > 0); assert.equal(r.quantities.total, null); assert.ok(r.quantities.rows.every(r => r.rate === null)); });
test('result does not stay bound after architectural or service edits', async () => { const p = fixture(), r = await createEngineeringPackage(p); p.services.electrical.loads[0].powerW++; assert.equal(await verifyBinding(r, p), false); });
test('async run snapshots inputs before callers can edit them', async () => { const p = fixture(), expected = structuredClone(p), pending = createEngineeringPackage(p); p.projectId = 'CHANGED'; const r = await pending; assert.equal(r.projectId, 'MEP-DEMO'); assert.equal(await verifyBinding(r, expected), true); });
test('change comparison tracks moved devices', async () => { const p = fixture(), a = await createEngineeringPackage(p); p.services.electrical.loads[0].position.x -= .2; const b = await createEngineeringPackage(p); const diff = comparePackages(a, b); assert.equal(diff.architectureChanged, false); assert.ok(diff.changed.includes('SO1')); });
test('plugin cannot elevate the package or its discipline to construction approval', async () => { const plugin = { id: 'custom', run: () => ({ ...emptyDiscipline('custom'), constructionApproved: true, codeCompliance: 'PASS' }) }; const r = await createEngineeringPackage(fixture(), { disciplines: ['custom'], plugins: [plugin] }); assert.equal(r.disciplines[0].constructionApproved, false); assert.equal(r.disciplines[0].codeCompliance, 'NOT_EVALUATED'); });
test('unknown and duplicate discipline names fail explicitly', async () => { await assert.rejects(createEngineeringPackage(fixture(), { disciplines: ['unknown'] }), { code: 'UNKNOWN_DISCIPLINE' }); await assert.rejects(createEngineeringPackage(fixture(), { disciplines: ['hvac', 'hvac'] }), { code: 'DISCIPLINES_REQUIRED' }); });
test('bad units, duplicate room IDs, and nonfinite coordinates are rejected', () => { const a = fixture(); a.units = 'mm'; assert.throws(() => validateProject(a), { code: 'CONTRACT_OR_UNITS' }); const b = fixture(); b.architecture.rooms.push(b.architecture.rooms[0]); assert.throws(() => validateProject(b), { code: 'DUPLICATE_ID' }); const c = fixture(); c.architecture.rooms[0].polygon[0].x = NaN; assert.throws(() => validateProject(c)); });
test('hash refuses accessors and cycles instead of silently normalizing them', async () => { const a = {}; a.self = a; await assert.rejects(hash(a)); const b = { get secret() { throw new Error('must never execute'); } }; await assert.rejects(hash(b), { code: 'ACCESSOR_NOT_ALLOWED' }); });
test('clash detection uses absolute z rather than only floor or XY', () => { const p = fixture(), r = (id, discipline, z) => ({ id, discipline, systemId: id, status: 'PROPOSED', widthM: .1, heightM: .1, clearanceM: 0, points: [{ x: 2, y: 2, z }, { x: 4, y: 2, z }] }); const a = { devices: [], routes: [r('a', 'a', 1)] }, b = { devices: [], routes: [r('b', 'b', 4)] }; assert.equal(coordinate(p, [a, b]).clashes.filter(x => x.kind === 'SERVICE_SERVICE').length, 0); b.routes[0] = r('b', 'b', 1); assert.ok(coordinate(p, [a, b]).clashes.some(x => x.kind === 'SERVICE_SERVICE')); });
test('explicit aligned riser retains true elevations and both visible levels', async () => {
  const p = fixture(); p.architecture.levels.push({ id: 'L2', elevationM: 3.5, heightM: 3.2 });
  p.services.low_current.devices.push({ id: 'R0', kind: 'RISER_NODE', levelId: 'L1', position: { x: 8, y: 2, z: .5 } }, { id: 'R1', kind: 'RISER_NODE', levelId: 'L2', position: { x: 8, y: 2, z: 4.5 } });
  p.services.risers = [{ id: 'RISER1', discipline: 'low_current', fromId: 'R0', toId: 'R1', layer: 'T-RISER', widthM: .05, heightM: .05, clearanceM: .02 }];
  const r = await createEngineeringPackage(p, { disciplines: ['low_current'] }), rise = r.disciplines[0].routes.find(r => r.id === 'RISER1');
  assert.equal(rise.lengthM, 4); assert.deepEqual(rise.levelIds, ['L1', 'L2']); assert.ok(r.issues.some(i => i.code === 'SLAB_PENETRATION_REVIEW'));
});
